/* ——— Para saber mais: conceitos e referências técnicas ———
   Apoio ao inspetor nos módulos do núcleo de medicamentos. Não é norma: não
   capitula infração, não vira citação e não entra no relatório. Traz o
   conceito por trás da verificação e a referência técnica usual (Farmacopeia,
   ABNT, OMS, USP), para contextualizar a conversa com o responsável técnico.
   Uso: SaberMais.html(modulo, chave) → <details> ou ''. */
(function(){
 if(window.SaberMais)return;
 const S={
 manip:{
  'i2.1':[['Prazo de guarda de documentos','Controlados (Portaria 344/1998, art. 64): livros, balanços e comprovantes de movimentação, inclusive receitas e notificações retidas, 2 anos. SNGPC (RDC 22/2014): transmissão a cada 1 a 7 dias e cópia de segurança por 2 anos. RDC 67/2007, item 5.10.4: justificativas técnicas, contratos e requisições, 1 ano. Para ordens de manipulação, laudos e registros do controle de qualidade, a regra prática é guardar ao menos pelo prazo de validade da preparação somado ao período em que ela pode ser questionada; o prazo adotado deve estar no procedimento de documentação da farmácia.']],
  'i9.3':[['Prazo de guarda de documentos','Controlados (Portaria 344/1998, art. 64): livros, balanços e comprovantes de movimentação, inclusive receitas e notificações retidas, 2 anos. SNGPC (RDC 22/2014): transmissão a cada 1 a 7 dias e cópia de segurança por 2 anos. RDC 67/2007, item 5.10.4: justificativas técnicas, contratos e requisições, 1 ano. Para ordens de manipulação, laudos e registros do controle de qualidade, a regra prática é guardar ao menos pelo prazo de validade da preparação somado ao período em que ela pode ser questionada; o prazo adotado deve estar no procedimento de documentação da farmácia.'],['Escrituração e balanços','Livros de registro específico com termos de abertura e encerramento da vigilância (Portaria 344, art. 63), ou escrituração no SNGPC. BSPO e BMPO anuais entregues até 31 de janeiro do ano seguinte, quando aplicáveis (arts. 68 e 69). No BSPO é vedado ajuste por fator de correção (art. 68, § 5º).']],
  'i3.2':[['Saúde ocupacional','O ASO é emitido dentro do PCMSO (NR-7). Quem manipula hormônios, antibióticos, citostáticos ou imunossupressores está exposto a agentes de risco, e o PCMSO deve prever exames específicos para essa exposição. A NR-32 trata da segurança do trabalhador em serviços de saúde, inclusive do manuseio de medicamentos perigosos.']],
  'i4.1':[['Classificação dos resíduos','Resíduo de medicamento, de matéria-prima vencida e de embalagem contaminada com fármaco é do Grupo B (químico) na RDC 222/2018. A periculosidade de cada substância está na FDS (ficha com dados de segurança, ABNT NBR 14725). A ABNT NBR 10004 classifica resíduos sólidos em perigosos e não perigosos.'],['Logística reversa','Medicamentos domiciliares vencidos ou em desuso devolvidos pela população seguem o sistema de logística reversa do Decreto nº 10.388/2020, separado do resíduo gerado pela própria farmácia.']],
  'i5.9':[['Limpeza de vidraria e utensílios','Remover o resíduo logo após o uso, lavar com detergente neutro e escova macia (abrasivo risca a vidraria e altera o volume da volumétrica), enxaguar em água corrente e fazer o enxágue final com água purificada. Secar ao ar em local protegido ou em estufa: a vidraria volumétrica tolera a estufa até o limite do fabricante (cerca de 250 °C no borossilicato 3.3), com aquecimento e resfriamento lentos, nunca em chapa aquecedora. Referência: RDC nº 67/2007, Anexo I, itens 4.9 e 6.1; BRAND, Information on Volumetric Measurement.'],['Contaminação cruzada','Utensílios das salas de hormônios, antibióticos e citostáticos são separados e identificados por classe terapêutica; a lavagem dentro do laboratório só é admitida por procedimento escrito e em horário distinto da manipulação. O procedimento escrito de prevenção de contaminação cruzada é exigido. Referência: RDC nº 67/2007, Anexo I, itens 4.9 e 8.6; Anexo III, item 2.10.'],['Guarda','Material limpo guardado protegido de poeira, separado do sujo, identificado para uso interno ou externo. Referência: RDC nº 67/2007, Anexo I, itens 5.4.2 e 6.1.']],
  'i5.8':[['Faixas de armazenamento (Farmacopeia Brasileira)','Temperatura ambiente: 15 a 30 °C. Local fresco: 8 a 15 °C. Refrigerador: 2 a 8 °C. A umidade não tem limite geral: segue a especificação do fabricante e a natureza da substância. Higroscópicas pedem recipiente bem fechado e, quando indicado, dessecante; fotossensíveis, recipiente âmbar ou opaco.'],['Situação da matéria-prima','Quarentena, em análise, aprovado e reprovado são estados documentados, não apenas lugares: o rótulo interno e o registro do controle de qualidade devem dizer o mesmo. A saída segue o vencimento (primeiro que vence, primeiro que sai — FEFO), não só a ordem de chegada, e há política escrita para matéria-prima próxima do vencimento. Referência: RDC nº 67/2007, Anexo I, itens 7.2.7, 7.4.5, g, e 15.4.4; OMS, TRS 1025 (2020), Anexo 7, seção 13 (rotação de estoque).']],
  'i6.2':[['Referência analítica','A Farmacopeia Brasileira é o código oficial. Quando ela não tiver monografia, podem ser usadas farmacopeias estrangeiras admitidas pela Anvisa (RDC nº 511/2021). O certificado do fornecedor não dispensa os ensaios da farmácia: ele é conferido contra a especificação e contra o que a farmácia mede.'],['Ensaios típicos de recebimento','No recebimento, no mínimo: caracteres organolépticos, solubilidade, pH, peso, volume, ponto de fusão e densidade, conforme as características físicas da matéria-prima, além da avaliação do laudo do fabricante ou fornecedor. O objetivo é confirmar identidade e detectar troca ou degradação, não repetir toda a monografia; sem monografia, vale literatura científica pertinente. Referência: RDC nº 67/2007, Anexo I, itens 7.3.10 e 7.3.10.1.'],['Picnômetro','Frasco de vidro de volume exato, com tampa esmerilhada atravessada por um capilar que elimina o excesso de líquido. Serve para medir densidade de líquidos na recepção de matéria-prima (glicerina, propilenoglicol, álcool, óleos) e em produto acabado, e para converter massa em volume. Referência: Farmacopeia Brasileira, 8ª ed., método geral de densidade de massa e densidade relativa.'],['Como usar o picnômetro','Limpo e seco: pesar vazio (m0). Encher com água purificada a 20 °C, tampar, secar por fora e pesar (m1). Esvaziar, secar, encher com a amostra a 20 °C e pesar (m2). Densidade relativa (Farmacopeia Brasileira, a 20 °C) = (m2 − m0) ÷ (m1 − m0). Densidade de massa = (m2 − m0) ÷ volume do picnômetro. A temperatura importa: fora de 20 °C o resultado muda, por isso o banho termostatizado.'],['Densímetro e alcoômetro','São alternativas por flutuação, mais rápidas e menos exatas: o alcoômetro já vem graduado em teor alcoólico (°GL, em volume, ou °INPM, em massa) e deve ser lido na temperatura da escala ou corrigido por tabela. Referência: Farmacopeia Brasileira, 8ª ed., métodos gerais de densidade relativa e de alcoometria.'],['Solubilidade (termos da Farmacopeia)','Partes de solvente para 1 parte de soluto: muito solúvel, menos de 1; facilmente solúvel, 1 a 10; solúvel, 10 a 30; ligeiramente solúvel, 30 a 100; pouco solúvel, 100 a 1.000; muito pouco solúvel, 1.000 a 10.000; praticamente insolúvel, mais de 10.000.'],['pHmetro','Calibrar no dia do uso com pelo menos dois tampões que englobem o pH esperado (usualmente 4,0 e 7,0, ou 7,0 e 10,0), à temperatura de medição. A USP aceita inclinação (slope) de 90% a 105% e desvio do zero (offset) de até ±30 mV; um tampão de verificação deve ler a ±0,05 do valor nominal. Eletrodo guardado em solução própria, nunca seco nem em água purificada. Referência: USP <791> pH; Farmacopeia Brasileira, 8ª ed., método geral de determinação do pH.'],['Faixa ou ponto de fusão','Identifica e indica pureza de sólidos: impurezas abaixam e alargam a faixa de fusão. É feito em aparelho calibrado com substâncias de referência. Referência: Farmacopeia Brasileira, 8ª ed., método geral de temperatura e faixa de fusão; USP <741> Melting Range or Temperature.'],['Perda por dessecação e teor de água','Perda por dessecação mede tudo o que evapora na condição do ensaio; o método de Karl Fischer mede só água. O resultado entra no fator de correção quando a especificação é na base seca. Referência: Farmacopeia Brasileira, 8ª ed., métodos gerais de perda por dessecação e de determinação de água; RDC nº 67/2007, Regulamento Técnico, item 5.18.6.']],
  'i6.3':[['Calibração e verificação da balança','Calibração é feita por laboratório acreditado (RBC/Inmetro) e gera certificado com a incerteza de medição. Verificação é a checagem de rotina com pesos-padrão, feita pela farmácia e registrada. As duas são necessárias: o certificado não substitui a verificação do dia. Referência: RDC nº 67/2007, Anexo I, item 5, alínea a; ABNT NBR ISO/IEC 17025; USP <1251>.'],['Carga mínima','Toda balança tem uma massa abaixo da qual o erro relativo fica grande demais (conceito de carga mínima ou “minimum weight”, USP <41> e <1251>). Pesar microgramas de fármaco de baixa dose numa balança de faixa alta é o erro clássico: por isso existem as diluições padronizadas.'],['Local da pesagem','Mesa estável, nivelada, longe de corrente de ar e de vibração, com exaustão que não perturbe a leitura. Referência: RDC nº 67/2007, Anexo I, item 5, alínea a; USP <1251> Weighing on an Analytical Balance.'],['Balança analítica','Resolução (d) de 0,1 mg (0,0001 g, quatro casas decimais em gramas) ou menor, capacidade típica de 100 a 250 g, classe de exatidão I. Usada para fármacos em miligramas, diluições e controle de qualidade.'],['Balança semianalítica × analítica','A diferença está na resolução (d): a semianalítica lê 1 mg (0,001 g, três casas) — alguns fabricantes chamam assim também a de 0,01 g —; a analítica lê 0,1 mg (quatro casas) ou menos. Em geral, a analítica é de classe de exatidão I e a semianalítica, de classe II, mas a classe depende do intervalo de verificação (e) e do número de divisões, não só de d. Confira o “d” e a classe na plaqueta, não o nome comercial. Referência: OIML R 76-1 (instrumentos de pesagem não automáticos).'],['Capela de proteção da balança','É a câmara com portinhas de vidro que envolve o prato (em inglês, draft shield). Deve ser usada sempre que se opera balança analítica (0,1 mg ou menos): coloca-se o recipiente, fecham-se as portas e só se registra a leitura estável. Com a porta aberta, correntes de ar e a própria respiração do operador alteram a leitura. Referência: USP <1251> (Weighing on an Analytical Balance), que aponta a porta aberta como causa de erro e manda fechar a porta antes de registrar o peso. Não é o mesmo que a cabine de exaustão, que protege o operador do pó.'],['Balança semianalítica','Resolução de 1 mg (0,001 g) na maioria dos modelos; alguns fabricantes chamam assim também balanças de 0,01 g — confira o “d” na etiqueta. Classe de exatidão II. Usada para bases, excipientes e quantidades maiores, em que a resolução de 1 mg já dá erro relativo pequeno.'],['Qual balança usar','A escolha é pela menor massa a pesar, não pelo hábito: quanto menor a massa, mais fina a resolução exigida. A massa pesada deve ficar acima do peso mínimo da balança, obtido no local de uso pela repetibilidade (2 × desvio padrão ÷ massa ≤ 0,10%), e não apenas acima da carga mínima (Mín) da plaqueta; abaixo dele, usa-se balança mais sensível ou diluição padronizada. Referência: RDC nº 67/2007, Anexo I, item 5.1.3; USP <41> Balances.'],['Cabine de exaustão de pesagem','É a proteção com exaustão sobre a balança, para conter o pó. Obrigatória na prática sempre que o pó puder se dispersar: pós finos em geral e, sobretudo, hormônios, antibióticos, citostáticos e outras substâncias do Anexo III da RDC 67/2007, onde a pesagem é feita dentro da própria sala. Cabine de pesagem (enclausuramento de balança) é diferente de capela química de laboratório: a de pesagem tem fluxo de ar baixo e laminar para não perturbar a leitura; capela química forte faz a balança analítica oscilar. Solventes voláteis vão para capela química, não para a de pesagem.']],
  'i6.4':[['Água purificada','A monografia da Farmacopeia controla condutividade e carbono orgânico total (COT), além da pureza microbiológica (limite usual de 100 UFC/mL). Na manipulação, a água purificada é armazenada por menos de 24 horas, com sanitização do recipiente a cada troca (RDC nº 67/2007, Anexo I, item 7.5.2.5).'],['Sistema','Osmose reversa, deionização e lâmpada UV dependem de manutenção: troca de resinas e carvão, sanitização periódica e registro. A coleta segue procedimento escrito, e um dos pontos deve ser o local de armazenamento; a OMS orienta amostrar nos pontos de uso, como a água é de fato usada, e não só na saída do equipamento. Referência: RDC nº 67/2007, Anexo I, itens 7.5.2.1 a 7.5.2.3; OMS, TRS 1033 (2021), Anexo 3 (água para uso farmacêutico).']],
  'i6.5':[['Diluição geométrica','Para misturar pequena quantidade de fármaco com grande quantidade de excipiente: mistura-se o fármaco com volume igual de excipiente e, a cada etapa, dobra-se o volume até incorporar todo o diluente. Garante homogeneidade em doses baixas e é obrigatória nas diluições de baixo índice terapêutico. Referência: RDC nº 67/2007, Anexo II, item 2.12.2; Allen, The Art, Science, and Technology of Pharmaceutical Compounding (APhA).'],['Fator de correção','A massa pesada corrige a diferença entre sal e base (fator de equivalência), o teor declarado no certificado e a água ou umidade quando a especificação for na base seca. O cálculo deve estar registrado na ordem de manipulação. Referência: RDC nº 67/2007, Regulamento Técnico, item 5.18.6.'],['Escolha da cápsula','A cápsula é escolhida pelo volume do pó, não pela massa. Capacidade aproximada das cápsulas duras de gelatina: nº 000 1,37 mL; 00 0,91 mL; 0 0,68 mL; 1 0,50 mL; 2 0,37 mL; 3 0,30 mL; 4 0,21 mL. Os valores variam entre fabricantes e linhas (a 00 de HPMC Vcaps tem 0,95 mL). Referência: Capsugel (Lonza), tabelas de tamanho Coni-Snap e Vcaps.'],['Peso médio (Farmacopeia Brasileira)','Pesar individualmente 20 unidades. Nas cápsulas duras, pesar cada cápsula cheia, esvaziar sem perder o invólucro, pesar a cápsula vazia; o conteúdo é a diferença. Peso médio = soma dos conteúdos ÷ 20.'],['Limites de variação','Cápsulas duras: menos de 300 mg, ±10%; 300 mg ou mais, ±7,5%. Comprimidos: até 80 mg, ±10%; mais de 80 e menos de 250 mg, ±7,5%; 250 mg ou mais, ±5%. Tolera-se no máximo duas unidades fora dos limites, e nenhuma acima ou abaixo do dobro da porcentagem. Referência: Farmacopeia Brasileira, 8ª ed., método geral de determinação de peso; RDC nº 67/2007, Anexo I, item 9.1.1.'],['Exemplo','Peso médio de 250 mg em cápsula: limite ±10% = 225 a 275 mg; o dobro (±20%) = 200 a 300 mg. Se três unidades ficarem fora de 225–275 mg, ou uma abaixo de 200 mg, o lote não atende. Referência: Farmacopeia Brasileira, 8ª ed., método geral de determinação de peso.'],['Desvio padrão relativo','DPR (%) = desvio padrão ÷ peso médio × 100 (o coeficiente de variação). Mostra a homogeneidade do enchimento: DPR crescente entre lotes indica problema de fluxo do pó, de nivelamento no encapsulador ou de mistura, antes mesmo de alguma unidade sair do limite. Referência: RDC nº 67/2007, Anexo I, item 9.1.3.'],['Fator de correção — o que é','É o número pelo qual se multiplica a quantidade prescrita para chegar à massa que deve ser pesada. Existem três causas independentes, que se multiplicam: equivalência sal/base (ou forma hidratada), teor da matéria-prima e diluição usada. Referência: RDC nº 67/2007, Regulamento Técnico, item 5.18.6 (fatores de conversão, correção e equivalência).'],['Fator de equivalência (sal, base, hidrato)','FEq = massa molar da forma usada ÷ (massa molar da forma prescrita × número de moléculas). Exemplo: prescrição de 50 mg de zinco elementar usando sulfato de zinco heptaidratado (massa molar 287,56) — FEq = 287,56 ÷ 65,38 = 4,40, logo pesam-se 220 mg do sal. Quando a prescrição já está em sal, não se aplica FEq. Em controlados, o fator de equivalência base/sal só é permitido em formulação magistral, com as quantidades identificadas no rótulo (Portaria 344, art. 52, § 4º).'],['Fator de teor e de umidade','Se o certificado declara teor de 98%, FC = 100 ÷ 98 = 1,020. Se a especificação é na base seca e o lote tem 5% de umidade (ou perda por dessecação), FC = 100 ÷ (100 − 5) = 1,053. Use o teor do certificado do lote em uso, não o da monografia. Referência: RDC nº 67/2007, Regulamento Técnico, item 5.18.6; Anexo I, item 7.4.5, d.'],['Fator de diluição','Para diluição 1:10 (1 parte de fármaco em 10 partes totais), FD = 10; para 1:100, FD = 100. A diluição deve estar padronizada, identificada com o alerta de diluído e o fator de diluição, e registrada, com seu próprio lote e validade. Referência: RDC nº 67/2007, Anexo I, item 7.4.6, b; Anexo II, itens 2.12.1 a 2.12.3.'],['Juntando tudo','Massa a pesar = dose prescrita × FEq × FC de teor × FC de umidade × FD. Exemplo: 5 mg de fármaco (sal com FEq 1,12), teor 99%, diluição 1:10 → 5 × 1,12 × 1,010 × 10 = 56,6 mg da diluição. A ordem de manipulação deve mostrar cada fator e o cálculo, para que a conferência seja possível. Referência: RDC nº 67/2007, Regulamento Técnico, item 5.18.6; Anexo I, item 8.4.'],['Onde o fiscal olha','Na ordem de manipulação: fatores usados, origem do teor (certificado do lote), cálculo e dupla conferência da pesagem, obrigatória com registro em baixo índice terapêutico e nas salas do Anexo III. Referência: RDC nº 67/2007, Anexo I, item 8.4; Anexo II, itens 2.11.4 e 2.12.1; Anexo III, itens 2.15.3 e 2.15.6.']],
  'i7.1':[['Baixo índice terapêutico','São fármacos com estreita margem de segurança, cuja dose terapêutica é próxima da tóxica: um erro pequeno de pesagem ou de homogeneidade tem efeito clínico. Por isso a norma exige dupla checagem, diluição geométrica padronizada e análise de teor de cada diluído, com monitoramento do armazenado. Referência: RDC nº 67/2007, Regulamento Técnico, item 4 (definição); Anexo II, itens 2.11.4 e 2.12.1 a 2.12.3.']],
  'i7.2':[['Contenção','Salas de hormônios, antibióticos e citostáticos existem para proteger o produto e as pessoas: antecâmara, pressão negativa em relação às áreas adjacentes e exaustão com filtro impedem que o pó saia da sala. Utensílios separados e identificados por classe terapêutica evitam contaminação cruzada. Referência: RDC nº 67/2007, Anexo III, itens 2.7, 2.7.2 e 2.10.'],['Medicamentos perigosos','A lista do NIOSH (EUA) de medicamentos perigosos em serviços de saúde é a referência técnica usual para classificar o risco de exposição ocupacional e definir EPI. Referência: NIOSH List of Hazardous Drugs in Healthcare Settings, 2024 (DHHS/NIOSH Publicação nº 2025-103); NR-32.']],
  'i7.5':[['Citostáticos','Além das exigências da sala, a NR-32 trata do preparo de quimioterápicos antineoplásicos: EPI, capacitação, procedimentos para derramamento e descarte como resíduo químico perigoso.']],
  'i7.6':[['Referência','A Farmacopeia Homeopática Brasileira (4ª edição, RDC nº 1.027/2026) define métodos de preparo, escalas (decimal, centesimal e cinquenta milesimal), insumos inertes e teores alcoólicos. O alcoômetro confere o grau do insumo líquido; a vidraria reutilizada passa por processo de inativação descrito em procedimento.']],
  'i8.1':[['Qualificação','Qualificação de instalação (QI), de operação (QO) e de desempenho (QD) respondem a perguntas diferentes: foi instalado como projetado, funciona nas faixas especificadas, e controla o pó na rotina real. Após mudança relevante ou no prazo definido, há requalificação. Referência: RDC nº 67/2007, Anexo I, item 8.7 (exaustão devidamente qualificada); OMS, TRS 1019 (2019), Anexo 3 (guia de validação).'],['Captação localizada','A eficácia depende da velocidade do ar na boca do captor e da distância até a fonte de pó. A ABNT NBR 16401 trata de instalações de ar-condicionado; para captação localizada, o manual de ventilação industrial da ACGIH é a referência técnica usual.']],
  'i9.1':[['Validade das receitas (situação em 2026)','Notificação A (amarela — A1, A2, A3), Notificação B (azul — B1) e Notificação B2 (azul — anorexígenos): 30 dias, válidas em todo o território nacional (RDC 873/2024). Notificação especial de retinoides (branca — C2): 30 dias, no máximo 5 ampolas ou 30 dias de tratamento, com Termo de Consentimento Pós-Informação; no Estado de São Paulo, para paciente em idade fértil, a receita vale no máximo 7 dias e deve ser revalidada mensalmente (Portaria CVS nº 23/2003, art. 4º). Talidomida (C3): 20 dias (RDC 11/2011, alterada pela RDC 873/2024). Receita de Controle Especial (C1, C5 e adendos de A1, A2 e B1): 30 dias, em duas vias, válida em todo o território. Antimicrobianos: 10 dias, com retenção da segunda via (RDC 471/2021 e IN 360/2025); em tratamento prolongado, a mesma receita serve para novas compras por até 90 dias, se indicar uso contínuo e a quantidade para cada 30 dias. Agonistas do GLP-1: 90 dias, com retenção (IN 360/2025). Antiparkinsonianos e anticonvulsivantes: quantidade limitada a 6 meses de tratamento (Portaria 344, art. 59).'],['SNCR — o que é','O Sistema Nacional de Controle de Receituários (RDC 873/2024) é o sistema da Anvisa pelo qual a vigilância sanitária cadastra prescritores e distribui a numeração das Notificações de Receita e dos talonários. A numeração passa a ser nacional e única. O uso pelas vigilâncias é obrigatório desde 1º de julho de 2025. Não abrange a lenalidomida e as demais substâncias da lista C3 controladas pela RDC 735/2022.'],['SNCR — o que mudou para a farmácia','As Notificações A, B, B2 e de retinoides passaram a valer em todo o território nacional por 30 dias: acabou a restrição à dispensação de notificação de outra unidade federativa (foram revogados o parágrafo único do art. 41 e o § 3º do art. 52 da Portaria 344). O prescritor usa a numeração concedida pela vigilância da UF onde prescreve; a dispensação pode ocorrer em qualquer UF. Talonários impressos até 30/06/2025 sem numeração do SNCR podiam ser entregues até 18/07/2026 e continuam utilizáveis por prazo indeterminado. Roubo, furto ou extravio de notificações é comunicado pelo prescritor à vigilância, que cancela a numeração no sistema.'],['Receituário eletrônico (RDC 1.000/2025)','Notificações de Receita, Receitas de Controle Especial e receitas de retenção (antimicrobianos, GLP-1) podem ser eletrônicas, geradas só em serviços de prescrição integrados ao SNCR, com numeração individual do sistema. Notificações e Receitas de Controle Especial exigem assinatura eletrônica qualificada (ICP-Brasil); receitas de retenção, avançada ou qualificada. A notificação eletrônica dispensa a receita que a acompanha, e a receita de controle especial ou de retenção eletrônica é emitida em via única. Documento feito em papel e depois escaneado ou fotografado não é receituário eletrônico. A Anvisa tem até 30/09/2026 para disponibilizar no SNCR a numeração e o registro de uso das receitas eletrônicas (redação da RDC 1.028/2026).'],['Na dispensação e na inspeção','Para receita eletrônica, a farmácia deve: validar a assinatura no serviço do ITI (validar.iti.gov.br), conferir no SNCR se a numeração foi concedida àquele prescritor, e registrar a utilização no SNCR preenchendo todos os campos. O registro de uso substitui a anotação no verso da notificação e deve ser guardado em meio eletrônico pelo prazo da Portaria 344 (RDC 1.000/2025, art. 14; Portaria 344, art. 36, § 3º). Receituário físico não tem registro de uso no SNCR: a notificação física com número do SNCR é só consultada e segue a anotação e a retenção do papel (Cartilha Anvisa “SNCR e receituários controlados — cartilha para farmácias”, 1ª ed., set. 2026, tópico 10). Na inspeção, confira: notificações retidas com numeração do SNCR ou de talonário antigo válido; nas eletrônicas, o comprovante de registro de uso; e ausência de receitas “eletrônicas” que sejam só PDF ou foto sem validação.']],
  'i9.2':[['Ordem de manipulação','É o documento que acompanha todas as etapas da manipulação e liga a prescrição ao produto: fármacos, concentrações, lotes das matérias-primas, cálculos com fatores de correção, quantidades pesadas, conferência e aprovação do farmacêutico. É o ponto de partida da rastreabilidade. Referência: RDC nº 67/2007, Regulamento Técnico, itens 4 (definição) e 5.18.6; Anexo I, itens 8.4 e 9.1.2.']],
  'i10.1':[['Rastreabilidade ascendente e descendente','Ascendente: do produto entregue aos lotes de matéria-prima, fornecedor e certificado. Descendente: de um lote de matéria-prima a todos os pacientes que receberam fórmulas com ele. A amostragem testa as duas direções. Referência: RDC nº 67/2007, Anexo I, itens 7.2.10, 7.4.9 e 8.4.']],
  'i10.2':[['Prazo de uso','Na ausência de estudo próprio, o prazo de uso de manipulados costuma seguir literatura como a USP <795> (revisão 2023): aquosas sem conservante, 14 dias refrigeradas; aquosas com conservante, 35 dias; líquidos orais não aquosos, 90 dias; demais formas não aquosas e sólidas, 180 dias. O prazo adotado deve estar justificado no procedimento.'],['Compatibilidade','Base e ativo precisam ser compatíveis: carga (aniônico × catiônico), faixa de pH de estabilidade do fármaco e do conservante. Referência: Allen, The Art, Science, and Technology of Pharmaceutical Compounding (APhA).']],
  'i10.3':[['Conservação','Em líquidos, a eficácia do conservante depende do pH e da compatibilidade com o ativo. O pH medido é também um indicador de erro de preparo. Referência: USP <51> Antimicrobial Effectiveness Testing; Allen, The Art, Science, and Technology of Pharmaceutical Compounding (APhA).']],
  'i11.1':[['Pureza microbiológica','A amostragem deve ser asséptica e seguir o procedimento de coleta, com um ponto no local de armazenamento. O resultado é expresso em UFC por mL e comparado ao limite da monografia; tendência crescente, mesmo dentro do limite, pede investigação do sistema, com nova análise para confirmar a correção. Referência: RDC nº 67/2007, Anexo I, itens 7.5.2.2 a 7.5.2.4; Farmacopeia Brasileira, 8ª ed., monografia Água purificada.']],
  'i11.2':[['Uniformidade de conteúdo','Mede quanto cada unidade se afasta do valor declarado. A farmácia analisa teor e uniformidade de conteúdo de fórmulas com até 25 mg de fármaco por unidade, com prioridade às de até 5 mg, no mínimo uma fórmula a cada dois meses. No ensaio farmacopeico de uniformidade de doses unitárias, o critério é o valor de aceitação (VA ≤ 15,0 no primeiro estágio). Referência: RDC nº 67/2007, Anexo I, itens 9.2.3 e 9.2.3.1; Farmacopeia Brasileira, 8ª ed., método geral de uniformidade de doses unitárias.']],
  'i11.4':[['Água potável','O padrão de potabilidade é o da Portaria GM/MS nº 888/2021: ausência de coliformes totais e Escherichia coli em 100 mL, cloro residual livre mínimo de 0,2 mg/L e demais parâmetros físico-químicos. A limpeza da caixa d’água é semestral e registrada.']],
  'i11.5':[['Laboratório contratado','Laboratórios da REBLAS são habilitados pela Anvisa e seguem as Boas Práticas para Laboratórios Analíticos (RDC nº 1.039/2026), com sistema de gestão pela ABNT NBR ISO/IEC 17025.']],
  'i12.2':[['Transporte de termossensíveis','Embalagem térmica passiva (caixa isotérmica com gelo reutilizável) só mantém a faixa pelo tempo e na configuração em que foi testada. Gelo em contato direto com o produto pode congelar formulações refrigeradas. Referência: RDC nº 67/2007, Anexo I, item 13.1; OMS, TRS 961 (2011), Anexo 9, Suplemento 13 (qualificação de embalagens de transporte).']]
 },
 dist:{
  'pessoal':[['Saúde e segurança','Programa de controle médico (NR-7) com ASO; EPI adequado à atividade, com registro de entrega (NR-6), especialmente em câmara fria, empilhadeira e manuseio de produtos perigosos. A RDC 430/2020 exige requisitos de saúde, higiene e vestuário (art. 11) e treinamento com registro de eficácia (art. 12).']],
  'controlados':[['Controlados na distribuidora (Portaria 344/1998)','Exige Autorização Especial (AE) da empresa e dos clientes para as listas controladas; guarda sob chave em local exclusivo, sob responsabilidade do farmacêutico (art. 67); escrituração em livros com termos lavrados pela vigilância (art. 63) ou sistema aprovado; BSPO anual entregue até 31 de janeiro do ano seguinte (art. 68), sem ajuste por fator de correção (§ 5º); livros, balanços e comprovantes guardados por 2 anos (art. 64). A transportadora mantém cópia da AE das empresas atendidas (art. 32, § 1º).']],
  'documentacao':[['Gestão documental (RDC 430/2020)','Deve cobrir elaboração, revisão, aprovação, distribuição, treinamento, codificação, guarda e obsolescência, em papel ou meio eletrônico (art. 19). POPs seguidos e disponíveis no local de uso (art. 20), atualizados (art. 21) e sem ambiguidade (art. 22). Guarda de POPs e registros: 5 anos após a obsolescência (art. 24). Monitoramento de temperatura: 2 anos (art. 43, § 3º).'],['ABNT NBR ISO 9001','Não é exigência sanitária, mas a certificação ISO 9001 da empresa indica sistema de gestão estruturado; o Anexo I sugere pedir o certificado como documento anexo quando existir.']],
  'armazenamento':[['Faixas e zona climática','Farmacopeia Brasileira: ambiente 15 a 30 °C; refrigerado 2 a 8 °C. O Brasil está na zona climática IVb (30 °C / 75% UR) para estudos de estabilidade (RDC nº 318/2019): por isso a especificação do detentor do registro é o parâmetro de armazenagem.'],['FEFO','A expedição segue o vencimento (primeiro que vence, primeiro que sai), controlado pelo sistema e por endereçamento, não pela posição física do palete. Referência: OMS, TRS 1025 (2020), Anexo 7, seção 13 (rotação de estoque).'],['Temperatura cinética média (MKT)','Resume numa só temperatura o efeito de uma série de leituras sobre a degradação do produto. Ajuda a avaliar excursões curtas, mas não substitui a análise de cada excursão contra os dados de estabilidade do fabricante. Referência: USP <1079.2> Mean Kinetic Temperature in the Evaluation of Temperature Excursions.'],['Suplementos técnicos da OMS (TRS 961, Anexo 9)','Os 16 suplementos (2015) detalham o guia modelo de armazenagem e transporte de produtos sensíveis a tempo e temperatura: 1 escolha do local de armazéns; 2 projeto das instalações; 3 estimativa de capacidade; 4 segurança patrimonial e contra incêndio; 5 manutenção das instalações; 6 monitoramento de temperatura das áreas; 7 qualificação de áreas com temperatura controlada; 8 mapeamento térmico de áreas; 9 manutenção de equipamentos de refrigeração; 10 verificação da exatidão de dispositivos de controle e monitoramento; 11 qualificação de veículos refrigerados; 12 operações de transporte com temperatura controlada por via rodoviária e aérea; 13 qualificação de embalagens de transporte; 14 qualificação por perfil de rota; 15 monitoramento de temperatura e umidade no transporte; 16 gestão ambiental de gases refrigerantes e equipamentos.'],['Guarda de registros (RDC 430/2020)','POPs e registros: pelo menos 5 anos após a obsolescência (art. 24), com acesso restrito. Registros de monitoramento de temperatura e umidade: pelo menos 2 anos após a geração (art. 43, § 3º). Correção de registro só com justificativa e preservando o dado original (art. 23, § 1º).']],
  'qt-area':[['Mapeamento térmico','O guia da OMS (TRS 961, Anexo 9, Suplemento 8) recomenda mapear a área vazia e carregada, no verão e no inverno, por pelo menos 7 dias contínuos, com sensores em grade nas três dimensões e nos pontos críticos (portas, teto, próximo a fontes de calor). O resultado define onde ficam os sensores de rotina.'],['Como a OMS recomenda mapear (Suplemento 8)','Duração: não há limite formal, mas em armazéns e áreas ambiente recomenda-se no mínimo 7 dias consecutivos, incluindo 5 dias úteis e 2 de fim de semana. Sensores em grade no comprimento e na largura, a cada 5 a 10 metros. Altura: com pé-direito até 3,6 m, três níveis (piso, cerca de 1,2 m e cerca de 3,0 m); acima disso, colunas com sensores na base, no meio e no topo. Registradores calibrados em 3 pontos, com erro máximo de ±0,5 °C, certificado anexado ao relatório. Pontos quentes e frios mudam com a estação: por isso o estudo de verão e o de inverno. O relatório define onde ficam os sensores do monitoramento de rotina (Suplemento 6).'],['Qualificação da área (Suplemento 7)','A qualificação da área climatizada segue as etapas de instalação (QI), operação (QO) e desempenho (QD); o mapeamento de temperatura é a evidência de desempenho, e o monitoramento de rotina usa sensores posicionados conforme esse estudo. Referência: OMS, TRS 961 (2011), Anexo 9, Suplementos 7 e 8; RDC nº 430/2020, art. 43, § 1º.']],
  'termolabeis':[['Cadeia fria','Medicamento termolábil (temperatura máxima especificada de até 8 °C) não pode congelar nem aquecer: o congelamento costuma ser irreversível para insulinas e para vacinas adsorvidas em alumínio. A área ou o equipamento precisa de qualificação térmica que demonstre homogeneidade de temperatura no interior, antes do uso e após mudança significativa. Referência: RDC nº 430/2020, art. 3º, XVI e XXIII, e art. 40; OMS, Temperature sensitivity of vaccines (WHO/IVB/06.10); bula das insulinas (não congelar).'],['Falha de energia','O tempo que o equipamento mantém a faixa desligado (tempo de retenção) deve ser conhecido pelo teste de falha de energia da qualificação; ele define o plano de contingência e o prazo para acionar a fonte alternativa ou transferir a carga. Referência: RDC nº 430/2020, arts. 79 e 80; OMS, TRS 961 (2011), Anexo 9, Suplemento 7 (teste de falha de energia na QO).']],
  'qt-equip':[['Qualificação de equipamentos','QI confirma a instalação; QO, o funcionamento vazio (setpoint, uniformidade, alarmes, abertura de porta); QD, o desempenho carregado na rotina. Sensores e registradores devem ter certificado de calibração rastreável (RBC), calibrados antes do primeiro uso e em intervalos definidos. Referência: RDC nº 430/2020, art. 3º, XXII, art. 40 e art. 43, § 4º; OMS, TRS 961 (2011), Anexo 9, Suplementos 7 e 10.'],['Referências da OMS','Suplemento 9 (manutenção de equipamentos de refrigeração), Suplemento 10 (verificação da exatidão de controladores e sensores) e Suplemento 16 (gestão ambiental de gases refrigerantes).']],
  'transporte':[['Embalagem ativa e passiva','Ativa: temperatura controlada por equipamento que se ajusta ao clima externo (baú ou contêiner refrigerado). Passiva: caixa isolada com refrigerante, sem controle ativo, qualificada para uma configuração e um tempo. Perfis de temperatura externa como os da ISTA 7D são usados para testar embalagens passivas no verão e no inverno. Referência: RDC nº 430/2020, art. 3º, XXVIII e XXIX; OMS, TRS 961 (2011), Anexo 9, Suplemento 13; ISTA 7D.'],['Referências da OMS','Suplemento 11 (qualificação de veículos refrigerados), 12 (operações de transporte com temperatura controlada por via rodoviária e aérea), 13 (qualificação de embalagens de transporte), 14 (qualificação por perfil de rota) e 15 (monitoramento de temperatura e umidade no transporte).'],['Guias da Anvisa','Perguntas e respostas da RDC 430/2020 (Anvisa) esclarece a aplicação das boas práticas de distribuição, armazenagem e transporte. O Guia para Qualificação de Transporte dos Produtos Biológicos (Guia nº 02, versão 2, 2017) é a referência da Anvisa para estudos de qualificação de transporte e serve de modelo também para outros termolábeis.'],['Produtos perigosos','Medicamentos ou insumos classificados como perigosos para transporte (inflamáveis, corrosivos) seguem a regulamentação da ANTT e a identificação da ABNT NBR 7500; a periculosidade vem da FDS (ABNT NBR 14725).']],
  'qt-veiculo':[['Veículo e embalagem','Um baú qualificado não qualifica a caixa térmica, e vice-versa: cada solução de transporte tem sua qualificação, feita na pior condição de carga e de clima. Referência: RDC nº 430/2020, arts. 63, I, e 64, § 1º; OMS, TRS 961 (2011), Anexo 9, Suplementos 11 (veículos refrigerados) e 13 (embalagens).'],['Guias da Anvisa','Perguntas e respostas da RDC 430/2020 (Anvisa) esclarece a aplicação das boas práticas de distribuição, armazenagem e transporte. O Guia para Qualificação de Transporte dos Produtos Biológicos (Guia nº 02, versão 2, 2017) é a referência da Anvisa para estudos de qualificação de transporte e serve de modelo também para outros termolábeis.']],
  'qt-rota':[['Perfil de rota','O estudo registra a temperatura real do trajeto, com paradas, transbordos e portas abertas, nas estações extremas. É o que sustenta a dispensa de monitoramento contínuo prevista na RDC 430/2020.']],
  'recolhimento':[['Recolhimento','A RDC nº 55/2005 regula o recolhimento; a distribuidora participa na proporção do seu mapa de distribuição. A simulação anual testa, no pior caso da rede, se o mapa permite localizar e reconciliar as unidades em tempo.']],
  'desvios':[['Desvio, não conformidade e CAPA','Desvio é o afastamento de um procedimento ou especificação; a investigação busca a causa raiz (por exemplo, 5 porquês ou diagrama de Ishikawa), avalia outros lotes que possam ter sido afetados e define ação corretiva e preventiva (CAPA), com verificação de eficácia. Referência: RDC nº 430/2020, art. 26, §§ 3º e 4º; ICH Q9 (ferramentas de gestão de risco, como o diagrama de Ishikawa) e ICH Q10 (CAPA).']],
  'reclamacoes':[['Reclamação','Reclamação de desvio de qualidade (produto) vai ao fabricante ou ao detentor do registro para investigação, e o resultado é aditado ao registro; reclamação de distribuição, armazenagem ou transporte (atraso, avaria) é investigada pela própria empresa. As duas são registradas separadamente. Referência: RDC nº 430/2020, arts. 26 e 27.']],
  'sistemas':[['Validação de sistemas','Equipamentos e sistemas informatizados são validados antes do uso e após mudança significativa, com abordagem baseada em risco e as categorias de software do GAMP 5. A integridade de dados segue o princípio ALCOA+: atribuível, legível, contemporâneo, original e exato, além de completo, consistente, durável e disponível. Referência: RDC nº 430/2020, art. 40; ISPE, GAMP 5, 2ª ed. (2022); OMS, TRS 1033 (2021), Anexo 4 (integridade de dados).']],
  'qualificacao-sistemas':[['Trilha de auditoria','Em sistemas que registram lote, validade, temperatura ou liberação, a trilha de auditoria mostra quem alterou o quê e quando, e deve ser revisada periodicamente, não só existir. Referência: OMS, TRS 1033 (2021), Anexo 4 (integridade de dados); ISPE, GAMP 5, 2ª ed. (2022).']],
  'fornecedores':[['Qualificação','Qualificar o fornecedor vai além de conferir AFE e licença: a qualificação verifica requisitos específicos, é registrada e reavaliada periodicamente por indicadores. A consulta pública de AFE/AE mostra a situação na data consultada. Referência: RDC nº 430/2020, art. 72, §§ 1º a 3º.']],
  'residuos':[['Medicamentos vencidos','O resíduo da própria empresa segue a RDC 222/2018 e o PGRSS. Medicamentos domiciliares devolvidos pela população entram na logística reversa do Decreto nº 10.388/2020.'],['ABNT','ABNT NBR 10004 (classificação de resíduos sólidos), NBR 12235 (armazenamento de resíduos perigosos) e NBR 7500 (identificação para transporte de produtos perigosos) apoiam a avaliação do abrigo e da destinação.']],
  'ifa-rastreabilidade':[['CADIFA e CBPF','A CADIFA (RDC nº 359/2020) é a carta de adequação do dossiê do IFA, exigida no contexto do registro de medicamentos industrializados. O CBPF de IFA atesta boas práticas do fabricante do insumo. Nenhum dos dois, sozinho, comprova a qualidade de um lote: isso é papel do certificado de análise e da conferência de recebimento.'],['Fracionamento','Fracionar insumo é abrir a embalagem original: exige área adequada, rotulagem que preserve a identidade do fabricante e do lote e análise após o fracionamento (RDC nº 204/2006).']],
  'cq_atividades':[['Boas práticas de laboratório','A RDC nº 1.039/2026 remete os laboratórios de controle de qualidade de medicamentos ao guia da OMS (TRS 1052, Anexo 4, 2024). Nele estão os requisitos de equipamentos, água, reagentes, padrões, cepas e investigação de resultados.'],['Cepas de referência','A prática farmacopeica limita as culturas de trabalho a no máximo 5 passagens a partir da cepa de referência (ATCC ou equivalente), com registro de cada repique. Referência: USP <61> e <62> (sistema de lote-semente).']],
  'cq_padroes':[['Padrões','Padrão primário é o oficial (Farmacopeia Brasileira, USP, EP). Padrão secundário ou de trabalho é qualificado contra o primário, com certificado interno e prazo de reteste.']],
  'cq_oos':[['Resultado fora de especificação','A investigação começa no laboratório (erro analítico evidente?) e, sem causa laboratorial, passa ao processo. Retestar até “passar” sem justificativa não é permitido. Referência: FDA, Investigating Out-of-Specification (OOS) Test Results for Pharmaceutical Production, rev. 1 (2022).']]
 },
 drog:[
  [/Termol/i,[['Faixa e controle','Refrigerado: 2 a 8 °C (Farmacopeia Brasileira). Termômetro de máxima e mínima calibrado, leitura registrada ao menos duas vezes ao dia, e a máxima e a mínima zeradas após cada leitura. Nada de medicamento na porta ou em contato com a parede do fundo.'],['Vacinação','Farmácia que vacina segue a RDC nº 197/2017: equipamento exclusivo para imunobiológicos e plano de contingência para falha de energia.']]],
  [/Dispensa|Armazenamento/i,[['Temperatura ambiente','Ambiente, pela Farmacopeia: 15 a 30 °C. O termo-higrômetro fica no local onde os medicamentos estão, e a leitura precisa ser registrada, não só existir.'],['Genéricos e MIPs','A intercambialidade do genérico vem da Lei nº 9.787/1999. Medicamento isento de prescrição (MIP) pode ficar ao alcance do usuário; os demais, não.']]],
  [/Controlad|Antimicrob|SNGPC|receita/i,[['Validade das receitas (situação em 2026)','Notificação A (amarela — A1, A2, A3), Notificação B (azul — B1) e Notificação B2 (azul — anorexígenos): 30 dias, válidas em todo o território nacional (RDC 873/2024). Notificação especial de retinoides (branca — C2): 30 dias, no máximo 5 ampolas ou 30 dias de tratamento, com Termo de Consentimento Pós-Informação; no Estado de São Paulo, para paciente em idade fértil, a receita vale no máximo 7 dias e deve ser revalidada mensalmente (Portaria CVS nº 23/2003, art. 4º). Talidomida (C3): 20 dias (RDC 11/2011, alterada pela RDC 873/2024). Receita de Controle Especial (C1, C5 e adendos de A1, A2 e B1): 30 dias, em duas vias, válida em todo o território. Antimicrobianos: 10 dias, com retenção da segunda via (RDC 471/2021 e IN 360/2025); em tratamento prolongado, a mesma receita serve para novas compras por até 90 dias, se indicar uso contínuo e a quantidade para cada 30 dias. Agonistas do GLP-1: 90 dias, com retenção (IN 360/2025). Antiparkinsonianos e anticonvulsivantes: quantidade limitada a 6 meses de tratamento (Portaria 344, art. 59).'],['SNCR — o que é','O Sistema Nacional de Controle de Receituários (RDC 873/2024) é o sistema da Anvisa pelo qual a vigilância sanitária cadastra prescritores e distribui a numeração das Notificações de Receita e dos talonários. A numeração passa a ser nacional e única. O uso pelas vigilâncias é obrigatório desde 1º de julho de 2025. Não abrange a lenalidomida e as demais substâncias da lista C3 controladas pela RDC 735/2022.'],['SNCR — o que mudou para a farmácia','As Notificações A, B, B2 e de retinoides passaram a valer em todo o território nacional por 30 dias: acabou a restrição à dispensação de notificação de outra unidade federativa (foram revogados o parágrafo único do art. 41 e o § 3º do art. 52 da Portaria 344). O prescritor usa a numeração concedida pela vigilância da UF onde prescreve; a dispensação pode ocorrer em qualquer UF. Talonários impressos até 30/06/2025 sem numeração do SNCR podiam ser entregues até 18/07/2026 e continuam utilizáveis por prazo indeterminado. Roubo, furto ou extravio de notificações é comunicado pelo prescritor à vigilância, que cancela a numeração no sistema.'],['Receituário eletrônico (RDC 1.000/2025)','Notificações de Receita, Receitas de Controle Especial e receitas de retenção (antimicrobianos, GLP-1) podem ser eletrônicas, geradas só em serviços de prescrição integrados ao SNCR, com numeração individual do sistema. Notificações e Receitas de Controle Especial exigem assinatura eletrônica qualificada (ICP-Brasil); receitas de retenção, avançada ou qualificada. A notificação eletrônica dispensa a receita que a acompanha, e a receita de controle especial ou de retenção eletrônica é emitida em via única. Documento feito em papel e depois escaneado ou fotografado não é receituário eletrônico. A Anvisa tem até 30/09/2026 para disponibilizar no SNCR a numeração e o registro de uso das receitas eletrônicas (redação da RDC 1.028/2026).'],['Na dispensação e na inspeção','Para receita eletrônica, a farmácia deve: validar a assinatura no serviço do ITI (validar.iti.gov.br), conferir no SNCR se a numeração foi concedida àquele prescritor, e registrar a utilização no SNCR preenchendo todos os campos. O registro de uso substitui a anotação no verso da notificação e deve ser guardado em meio eletrônico pelo prazo da Portaria 344 (RDC 1.000/2025, art. 14; Portaria 344, art. 36, § 3º). Receituário físico não tem registro de uso no SNCR: a notificação física com número do SNCR é só consultada e segue a anotação e a retenção do papel (Cartilha Anvisa “SNCR e receituários controlados — cartilha para farmácias”, 1ª ed., set. 2026, tópico 10). Na inspeção, confira: notificações retidas com numeração do SNCR ou de talonário antigo válido; nas eletrônicas, o comprovante de registro de uso; e ausência de receitas “eletrônicas” que sejam só PDF ou foto sem validação.'],['Uso único e dispensação parcial','O receituário eletrônico é usado uma única vez: depois do registro de uso no SNCR não serve para nova dispensação (RDC 1.000/2025, art. 15). Notificação de Receita e Receita de Controle Especial não admitem registro parcelado no SNCR: se a farmácia dispensar quantidade menor que a prescrita, o restante não pode ser adquirido depois com a mesma receita. Só a receita sujeita à retenção (antimicrobianos e agonistas de GLP-1 — IN 360/2025, arts. 1º e 2º) admite aquisições posteriores, e apenas em tratamento prolongado, acima de 30 dias (RDC 471/2021, art. 4º, XIV): a receita deve indicar uso contínuo e a quantidade para cada 30 dias, e pode ser usada em novas compras por até 90 dias da emissão (art. 9º e § 1º); fora disso é aviada uma única vez (art. 13). Validade: antimicrobianos, 10 dias; GLP-1, 90 dias (IN 360/2025, arts. 1º, § 2º, e 2º, § 1º). No SNCR, a receita fica como “Receita utilizada parcialmente” até a última compra (Cartilha Anvisa “SNCR e receituários controlados — cartilha para farmácias”, 1ª ed., set. 2026, tópicos 17, 19 e 27). No papel, a Notificação de Receita é retida na primeira dispensação (Portaria 344, art. 35, § 5º).'],['Dados obrigatórios do paciente e do comprador (RDC 1.000/2025)','Notificação de Receita: paciente identificado por nome e CPF (passaporte, se estrangeiro); o endereço do paciente deixou de ser exigido (Portaria 344, art. 36, “d”, redação da RDC 1.000/2025). Comprador: nome e CPF (ou passaporte), endereço completo e telefone (art. 36, “i”). Receita de Controle Especial: nome e CPF do paciente (art. 55, “b”). Exceção: anabolizantes (C5) continuam exigindo nome e endereço do paciente e CID, porque a exigência está na Lei nº 9.965/2000, art. 1º, parágrafo único, que a RDC não altera. Modelo anterior impresso na vigência dele não é, sozinho, motivo de recusa (Cartilha Anvisa “SNCR e receituários controlados — cartilha para farmácias”, 1ª ed., set. 2026, tópico 3).'],['Escrituração, balanços e relações','Escrituração: no SNGPC, que substitui o Livro de Registro Específico (RDC 22/2014, arts. 3º e 35); o livro com termos de abertura e encerramento lavrados pela vigilância (Portaria 344, arts. 62, § 1º, e 63) só vale na exceção do município sem internet, com autorização da vigilância (RDC 22/2014, art. 35, § 1º). Transmissão a cada 1 a 7 dias, mesmo sem movimentação (RDC 22/2014, art. 10, § 3º). BMPO (vendas das listas A1, A2, A3, B2 e C4): trimestral, entregue pelo farmacêutico responsável até o dia 15 de abril, julho, outubro e janeiro, e anual até 31 de janeiro do ano seguinte (Portaria 344, art. 69, caput e § 1º). RMNRA (Relação Mensal de Notificações de Receita A): entregue com as notificações A retidas até o dia 15 de cada mês (arts. 42 e 72); a vigilância devolve as notificações em até 30 dias (art. 72, § 1º, redação da RDC 1.000/2025) e as notificações A eletrônicas podem ir em meio eletrônico (art. 72, § 2º). Não se aplicam à drogaria: o BSPO (art. 68), balanço de substâncias da farmácia com manipulação e da cadeia de insumos, e a RMV (art. 71), relação mensal de vendas da indústria e da distribuidora.']]],
  [/Documentos|Rastreab|Qualidade/i,[['Prazo de guarda de documentos','RDC 44/2009, art. 89: toda a documentação da drogaria fica no estabelecimento por no mínimo 5 anos, à disposição da fiscalização. Portaria 344/1998, art. 64: livros, balanços e comprovantes de movimentação de controlados (inclusive receitas e notificações retidas), 2 anos. SNGPC (RDC 22/2014): transmissão a cada 1 a 7 dias, mesmo sem movimentação, e cópia de segurança dos dados por 2 anos. Declaração de Serviço Farmacêutico: segunda via arquivada (RDC 44/2009, art. 81, § 4º).'],['Documentos da qualidade','POPs aprovados, assinados, datados e revisados periodicamente (RDC 44/2009, art. 87); política para produtos próximos ao vencimento descrita e conhecida (art. 51): é vedado dispensar medicamento cujo tratamento não possa ser concluído dentro da validade (art. 51, § 2º).']]],
  [/Servi[çc]os/i,[['Serviços farmacêuticos','Aferição de pressão e glicemia, aplicação de injetáveis e outros serviços seguem a RDC nº 44/2009. Perfurocortantes vão para coletor rígido (ABNT NBR 13853) e, como resíduo, para o Grupo E da RDC 222/2018.']]],
  [/Res[íi]duo|vencid/i,[['Destino','Resíduo da drogaria segue a RDC 222/2018. Medicamento devolvido pela população entra na logística reversa (Decreto nº 10.388/2020), em coletor identificado, separado do estoque e dos vencidos da própria loja.']]],
  [/Venda remota|Transporte|entrega/i,[['Entrega de termolábeis','Os termossensíveis vão em embalagem especial que mantenha a temperatura de conservação. A caixa térmica só mantém 2 a 8 °C na configuração e pelo tempo em que foi testada; gelo em contato com o produto pode congelar insulina. Referência: RDC nº 44/2009, art. 56, § 1º; OMS, TRS 961 (2011), Anexo 9, Suplemento 13.']]]
 ]
 };
 function esc(t){return String(t==null?'':t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c])}
 function caixa(itens){if(!itens||!itens.length)return '';return '<details class="sm-box"><summary>📘 Para saber mais — conceitos e referências técnicas</summary>'+itens.map(([t,p])=>'<p><b>'+esc(t)+'.</b> '+esc(p)+'</p>').join('')+'<p class="sm-nota">Apoio técnico. Não é norma, não gera irregularidade e não entra no relatório.</p></details>'}
 function html(mod,chave){if(mod==='drog'){const txt=String(chave||'');const m=S.drog.find(([re])=>re.test(txt));return caixa(m&&m[1])}return caixa((S[mod]||{})[chave])}

 /* Explicação por equipamento (cartões de equipamento da Manipulação): [regex do nome, [[título, texto]...]] */
 const EQ=[
  [/semianal/i,[['O que é','Resolução de 1 mg (0,001 g, três casas decimais em gramas) — alguns fabricantes chamam assim também a de 0,01 g; confira o “d” na etiqueta. Classe de exatidão II, geralmente sem câmara fechada ou com quebra-vento baixo.'],['Quando usar','Bases, excipientes, enchimento de cápsulas e massas em que 1 mg já é um erro relativo pequeno. Não serve para pesar fármaco de baixa dose, que fica abaixo do seu peso mínimo. Referência: RDC nº 67/2007, Anexo I, item 5.1.3; USP <41> Balances.'],['Como conferir','Mesmos cuidados da analítica: nivelamento, verificação diária com peso-padrão registrada, calibração RBC vigente e limpeza. Referência: RDC nº 67/2007, Anexo I, item 5, alínea a; USP <1251> Weighing on an Analytical Balance.']]],
  [/anal[íi]tica|uso exclusivo/i,[['O que é','Balança analítica: resolução (d) de 0,1 mg (quatro casas decimais em gramas) ou menor, em geral de classe de exatidão I. A semianalítica lê 1 mg (três casas), em geral classe II. Referência: OIML R 76-1 (instrumentos de pesagem não automáticos).'],['Capela de proteção','A câmara com portinhas de vidro que envolve o prato deve ser usada sempre que se opera balança analítica: portas fechadas durante a leitura, registrando só o valor estável. Porta aberta é causa de erro (USP <1251>).'],['Quando usar','Massas pequenas: fármacos em miligramas, baixo índice terapêutico, diluições e controle de qualidade. O limite prático é o peso mínimo da balança, calculado pela repetibilidade no local de uso; abaixo dele, o erro relativo é alto demais e se usa diluição padronizada. Referência: USP <41> Balances; RDC nº 67/2007, Anexo I, item 5.1.3.'],['Como conferir','Nivelada (bolha centralizada), em bancada estável, longe de porta, ar-condicionado e vibração; ligada com antecedência para estabilizar. Verificação no dia do uso com pesos-padrão e registro; calibração por laboratório RBC com certificado e etiqueta. Limpa antes e após cada pesagem: resíduo de pó no prato é contaminação cruzada. Referência: RDC nº 67/2007, Anexo I, item 5, alínea a; Anexo III, item 2.9; USP <1251>.']]],
  [/exaust|capela/i,[['O que é','Proteção com exaustão para conter pó e vapores. São equipamentos diferentes: cabine ou enclausuramento de pesagem (fluxo baixo, com filtro, para pós); capela química (fluxo forte, para solventes e vapores); cabine de segurança biológica (fluxo laminar com filtro HEPA, para proteção do produto e do operador). Referência: RDC nº 67/2007, Anexo I, item 8.7; Anexo III, item 2.7.3.1; NSF/ANSI 49 (cabines de segurança biológica).'],['Quando usar','Sempre que o pó puder se dispersar: pesagem e manipulação de sólidos e, obrigatoriamente, de hormônios, antibióticos e citostáticos. Solvente volátil vai para capela química, não para a cabine de pesagem: o fluxo forte faz a balança analítica oscilar. Referência: RDC nº 67/2007, Anexo I, item 8.7; Anexo III, item 2.7; USP <1251> (correntes de ar na pesagem).'],['Como conferir','Ligada durante a pesagem, sem objetos obstruindo a face, filtros trocados conforme programa e com registro, limpeza registrada e qualificação do sistema (item 8). Referência: RDC nº 67/2007, Anexo I, item 8.7.']]],
  [/pesos? padr/i,[['O que é','Massas de referência, classificadas pela OIML R 111 (E1, E2, F1, F2, M1…). Para balança analítica usam-se pesos E2 ou F1; para semianalítica, F1 ou F2.'],['Como conferir','Certificado de calibração RBC vigente, estojo fechado, manuseio com pinça ou luva (gordura e umidade da mão alteram a massa), valores e tolerâncias da verificação diária registrados. Referência: OIML R 111-1 (pesos-padrão); USP <41>.']]],
  [/pHmetro/i,[['Como conferir','Calibração no dia do uso com pelo menos dois tampões que englobem o pH medido (4,0 e 7,0, ou 7,0 e 10,0), tampões dentro da validade e registro da calibração. Inclinação (slope) de 90% a 105% e offset de até ±30 mV; tampão de verificação a ±0,05 do nominal. Eletrodo guardado em solução própria, nunca seco. Referência: USP <791> pH; Farmacopeia Brasileira, 8ª ed., método geral de determinação do pH.']]],
  [/picn[ôo]metro|dens[íi]metro/i,[['O que é','Picnômetro: frasco de vidro de volume exato, com tampa esmerilhada e capilar. Densímetro: flutuador graduado, mais rápido e menos exato. Referência: Farmacopeia Brasileira, 8ª ed., método geral de densidade de massa e densidade relativa.'],['Como usar','Pesar vazio (m0), com água purificada a 20 °C (m1) e com a amostra a 20 °C (m2). Densidade relativa = (m2 − m0) ÷ (m1 − m0). Usado na recepção de líquidos (glicerina, propilenoglicol, álcool, óleos) e em produto acabado. Referência: Farmacopeia Brasileira, 8ª ed., método geral de densidade de massa e densidade relativa.']]],
  [/ponto de fus/i,[['Como conferir','Aparelho verificado com substâncias de referência de ponto de fusão conhecido, com registro. Impurezas abaixam e alargam a faixa de fusão. Referência: Farmacopeia Brasileira, 8ª ed., método geral de temperatura e faixa de fusão; USP <741>.']]],
  [/inativa/i,[['O que é','Estufa usada na homeopatia para inativar, por calor seco, vidros e insumos reutilizáveis, eliminando a atividade medicamentosa residual, conforme a Farmacopeia Homeopática Brasileira.'],['Como conferir','Temperatura e tempo do procedimento escrito, termômetro calibrado e registro de cada ciclo. Referência: RDC nº 67/2007, Anexo V, item 3.4.1; Farmacopeia Homeopática Brasileira, 4ª ed.']]],
  [/^estufa/i,[['Para que serve','Secagem de vidrarias e utensílios, ensaio de perda por dessecação e, conforme a temperatura, despirogenização por calor seco. Referência: Farmacopeia Brasileira, 8ª ed., método geral de perda por dessecação; USP <1228.1> Dry Heat Depyrogenation.'],['Cuidados','Vidraria volumétrica (balão, pipeta volumétrica) pode ir à estufa até o limite do fabricante (cerca de 250 °C no borossilicato 3.3), com aquecimento e resfriamento lentos; choque térmico e chapa aquecedora alteram o volume calibrado. Termômetro calibrado e registro de temperatura. Referência: BRAND, Information on Volumetric Measurement; ISO 4787.']]],
  [/vidraria/i,[['Volumétrica × graduada','Volumétrica (balão volumétrico, pipeta volumétrica) mede um único volume, com a maior exatidão. Graduada (proveta, pipeta graduada) mede volumes variados, com exatidão menor. Béquer e erlenmeyer não são instrumentos de medida: a graduação é só aproximada. Referência: ISO 384 (princípios da vidraria volumétrica); ISO 4788 (provetas); ISO 3819 (béqueres).'],['Classe A × B','A classe A tem tolerância aproximadamente metade da classe B. Normas usuais: ABNT NBR ISO 1042 (balões), ISO 648 (pipetas volumétricas), ISO 835 (pipetas graduadas), ISO 4788 (provetas).'],['Para conter × para escoar','“In” ou “TC” (para conter): o volume é o que fica dentro, como no balão volumétrico e na maioria das provetas. “Ex” ou “TD” (para escoar): o volume é o que escoa, como na pipeta e na bureta. Confira a marcação gravada no vidro. Referência: ISO 384; ISO 4788 (provetas).'],['Uso correto','Escolher o recipiente com capacidade próxima ao volume (8 mL em proveta de 10 mL, não de 100 mL). Ler a parte inferior do menisco na altura dos olhos; a temperatura de referência da calibração é 20 °C. Verificação gravimétrica: massa de água contida ou escoada (conforme a marcação) convertida em volume pela densidade da água, com correção do empuxo do ar. Referência: ISO 384; ISO 4787 (ensaio de capacidade e uso).'],['Como conferir','Sem trincas ou lascas, graduação legível, identificada para uso interno ou externo e, nas salas de sensibilizantes, separada e identificada por classe terapêutica. Referência: RDC nº 67/2007, Anexo I, item 5.4.2; Anexo III, item 2.10.']]],
  [/utens[íi]lios|gral/i,[['Gral e pistilo','Porcelana: trituração e pulverização de sólidos (superfície áspera, retém mais). Vidro: substâncias que mancham ou são absorvidas pela porcelana e misturas oleosas ou coloridas. Referência: Allen, The Art, Science, and Technology of Pharmaceutical Compounding (APhA).'],['Como conferir','Limpos, secos, guardados protegidos, identificados para uso interno ou externo e separados por classe terapêutica nas salas do Anexo III. Referência: RDC nº 67/2007, Anexo I, itens 5.4.2 e 6.1; Anexo III, item 2.10.']]],
  [/encapsul/i,[['O que é','Equipamento manual (placas com furos por número de cápsula) ou semiautomático para encher cápsulas duras. Referência: Allen, The Art, Science, and Technology of Pharmaceutical Compounding (APhA).'],['Como conferir','Placas do número adequado, limpeza entre lotes registrada, nas salas de sensibilizantes placas separadas e identificadas por classe terapêutica. A uniformidade do enchimento se confere pelo peso médio (item 6.5). Referência: RDC nº 67/2007, Anexo I, itens 6.1 e 9.1.1; Anexo III, item 2.10.']]],
  [/termo-?higr/i,[['Como conferir','Instrumento calibrado (certificado RBC), posicionado longe de fonte de calor, de janela e do fluxo do ar-condicionado, com leitura de máxima e mínima registrada e zerada após cada leitura. O limite de temperatura e umidade de cada área é o definido pela farmácia com base nas especificações dos insumos, monitorado e registrado. Referência: RDC nº 67/2007, Anexo I, itens 4.2.1 e 8.8.']]],
  [/geladeira/i,[['Como conferir','2 a 8 °C (Farmacopeia Brasileira), termômetro de máxima e mínima calibrado com leitura registrada, sem alimentos nem itens estranhos, sem produtos na porta ou encostados na parede do fundo, degelo e limpeza registrados.']]],
  [/manômetro|diferencial/i,[['O que é','Mede a diferença de pressão entre a sala do Anexo III e a antecâmara ou o corredor. A sala de hormônios, antibióticos e citostáticos fica em pressão negativa em relação às áreas adjacentes, para o ar entrar e não sair com pó. Referência: RDC nº 67/2007, Anexo III, itens 2.7 e 2.7.2.'],['Como conferir','Leitura na faixa definida na qualificação, registrada, instrumento calibrado e com indicação visível para o manipulador. Referência: RDC nº 67/2007, Anexo III, itens 2.7 e 2.7.2.']]],
  [/alco[ôo]metro/i,[['Como conferir','Graduado em °GL (volume) ou °INPM (massa); lido na temperatura da escala (normalmente 20 °C) ou corrigido por tabela. Certificado de calibração e integridade do vidro. Referência: Farmacopeia Brasileira, 8ª ed., método geral de alcoometria.']]],
  [/agitador|misturador/i,[['Como conferir','Velocidade e tempo de mistura definidos no procedimento; limpeza entre lotes registrada; hastes e pás de material inerte. Referência: RDC nº 67/2007, Anexo I, itens 6.1 e 8.6.']]],
  [/chapa|banho/i,[['Como conferir','Controle de temperatura conferido com termômetro calibrado; banho-maria com água limpa e trocada; nada de aquecimento direto de inflamáveis em chapa aberta. Referência: RDC nº 67/2007, Anexo I, item 6.1; ficha com dados de segurança (FDS) do inflamável, ABNT NBR 14725.']]]
 ];
 function equip(nome){const m=EQ.find(([re])=>re.test(String(nome||'')));if(!m)return '';return '<details class="sm-box"><summary>📘 O que é e como conferir</summary>'+m[1].map(([t,p])=>'<p><b>'+esc(t)+'.</b> '+esc(p)+'</p>').join('')+'</details>'}
 const css='.sm-box{border:1px solid #cbd9c9;border-left:4px solid #4f7a52;border-radius:0 10px 10px 0;background:#f4f8f3;margin:8px 0;padding:0 12px}.sm-box>summary{cursor:pointer;padding:9px 0;font-weight:700;color:#2f5733;font-size:.84rem;list-style:none}.sm-box>summary::-webkit-details-marker{display:none}.sm-box p{margin:0 0 9px;font-size:.84rem;line-height:1.5;color:#26382a}.sm-box .sm-nota{font-size:.74rem;color:#5d6f60;border-top:1px dashed #cbd9c9;padding-top:6px}';
 function estilo(){if(document.getElementById('sm-style'))return;const s=document.createElement('style');s.id='sm-style';s.textContent=css;(document.head||document.documentElement).appendChild(s)}
 try{estilo()}catch(e){}
 window.SaberMais={html,equip,dados:S,estilo};
})();
